<?php
require_once __DIR__.'/includes/functions.php'; require_login(); $pageTitle='My reservations';
$stmt=$pdo->prepare("SELECT r.*,rooms.name AS room_name,rooms.image_url FROM reservations r JOIN rooms ON rooms.id=r.room_id WHERE r.user_id=? ORDER BY r.created_at DESC"); $stmt->execute([$_SESSION['user']['id']]); $rows=$stmt->fetchAll();
include __DIR__.'/includes/header.php';
?>
<section class="page-head"><div class="container"><div class="eyebrow mb-3">Your OneThree account</div><h1 class="section-title">My reservations.</h1><p class="muted">Welcome, <?= e($_SESSION['user']['full_name']) ?>.</p></div></section><section class="section pt-4"><div class="container"><?php if(!$rows): ?><div class="summary-panel text-center py-5"><h2 class="section-title">No reservations yet.</h2><p class="muted">Your next stay is waiting.</p><a class="btn btn-gold mt-3" href="rooms.php">Explore rooms</a></div><?php else: ?><div class="table-responsive"><table class="table table-dark align-middle"><thead><tr><th>Reservation</th><th>Room</th><th>Dates</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['reservation_code']) ?><div class="muted small"><?= e($r['created_at']) ?></div></td><td><?= e($r['room_name']) ?></td><td><?= e($r['check_in']) ?><br>to <?= e($r['check_out']) ?></td><td>₱<?= number_format($r['total_amount'],2) ?></td><td><span class="status status-<?= e($r['status']) ?>"><?= e($r['status']) ?></span></td><td><a href="confirmation.php?code=<?= urlencode($r['reservation_code']) ?>">Details</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></section>
<?php include __DIR__.'/includes/footer.php'; ?>
